import importlib.util
import os

import torch
import torch.nn as nn
import torch.nn.functional as F

VOXTURN_DIR = os.path.join(os.path.dirname(__file__), "..", "data", "models_dl", "voxturn_fe3d4a3")
NEW = "addr"

ADDRESSEE_QUESTION = {
    "labels": ["assistant", "other"],
    "phrasings": {"en": [
        "Is the user's last utterance addressed to the assistant or to someone else?",
        "Who is the user talking to right now: the assistant or someone else?",
        "Was the user's last sentence meant for the assistant?",
        "Should the assistant treat what the user just said as directed at it?",
        "Is the user speaking to the assistant, or to another person?",
        "Is the user's latest speech for the assistant or for someone else?",
    ]},
    "options": {"en": {"assistant": "the assistant", "other": "someone else"}},
}


def load_official_module(voxturn_dir=VOXTURN_DIR):
    spec = importlib.util.spec_from_file_location("voxturn_official", os.path.join(voxturn_dir, "voxturn.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def load_official(voxturn_dir=VOXTURN_DIR, device="cuda"):
    """The official model in its exact (unmerged, eager) mode."""
    mod = load_official_module(voxturn_dir)
    return mod, mod.VoxTurn.from_pretrained(os.path.abspath(voxturn_dir), device=device, fast=False)


class L1(nn.Module):
    """Wraps the official VoxTurn object `vt` (frozen) and adds the new adapter and head."""

    def __init__(self, mod, vt, lora_r=16):
        super().__init__()
        from peft import LoraConfig
        from peft.tuners.tuners_utils import BaseTunerLayer
        self.mod, self.vt = mod, vt
        vt.questions = dict(vt.questions)
        vt.questions["addressee"] = ADDRESSEE_QUESTION
        vt.llm.add_adapter(NEW, LoraConfig(r=lora_r, lora_alpha=2 * lora_r, lora_dropout=0.0,
                                           target_modules="all-linear"))
        for m in vt.llm.modules():                  # same LoRA dtype handling as VoxTurn's own adapter
            if isinstance(m, BaseTunerLayer):
                m.cast_input_dtype_enabled = False
        dev = vt.head.weight.device
        self.new_head = nn.Linear(vt.head.in_features, 1).to(dev)
        with torch.no_grad():                        # start from VoxTurn's head: same readout, new question
            self.new_head.weight.copy_(vt.head.weight)
            self.new_head.bias.copy_(vt.head.bias)
        self.set_new_adapter(False)

    # ------------------------------------------------------------------ adapters
    def set_new_adapter(self, enabled):
        """Activate VoxTurn's adapter alone, or together with the new one. Only the new adapter and head train."""
        self.vt.llm.base_model.set_adapter(["default", NEW] if enabled else ["default"])
        for n, p in self.vt.named_parameters():
            p.requires_grad_(f".{NEW}." in n and enabled)
        for p in self.new_head.parameters():
            p.requires_grad_(enabled)
        self.new_enabled = enabled

    def trainable_parameters(self):
        return [p for p in list(self.vt.parameters()) + list(self.new_head.parameters()) if p.requires_grad]

    # ------------------------------------------------------------------ forward
    def forward(self, waves, has_audio, texts, speakers, langs, questions):
        """Option logits (Q, max_options), as VoxTurn.logits() but differentiable and with the new head used for
        the "addressee" question. questions[b] = [(task, phrasing index), ...]."""
        vt, mod = self.vt, self.mod
        dev = vt.head.weight.device
        emb = vt.llm.get_input_embeddings()
        with torch.autocast("cuda", dtype=torch.bfloat16, enabled=dev.type == "cuda"):
            audio = vt.encode_audio(vt.mel(waves))
            seqs, opt_pos, blocks, tasks = [], [], [], []
            for b in range(len(questions)):
                ids = vt.context_ids(texts[b], speakers[b], langs[b],
                                     mod.MAX_AUDIO_CONTEXT if has_audio[b] else mod.MAX_CONTEXT)
                if has_audio[b]:
                    prefix = torch.cat([emb(torch.tensor(vt.seq_head + vt.audio_open, device=dev)), audio[b],
                                        emb(torch.tensor(vt.audio_close + ids, device=dev))], 0)
                else:
                    prefix = emb(torch.tensor(vt.seq_head + ids, device=dev))
                parts, start, spans = [prefix], len(prefix), []
                for task, k in questions[b]:
                    q_ids, q_pos = vt.prompt(task, langs[b], k)
                    parts.append(emb(torch.tensor(q_ids, device=dev)))
                    opt_pos.append([start + p for p in q_pos])
                    spans.append((start, len(q_ids)))
                    tasks.append(task)
                    start += len(q_ids)
                seqs.append(torch.cat(parts, 0))
                blocks.append(spans)
            x = nn.utils.rnn.pad_sequence(seqs, batch_first=True)
            x = F.pad(x, (0, 0, 0, -x.shape[1] % mod.LEN_BUCKET))
            if any(len(s) > 1 for s in blocks):
                kw = vt.isolating_mask(blocks, x.shape[1], dev)
                hid = vt.llm(inputs_embeds=x, attention_mask=kw["attention_mask"],
                             position_ids=kw["position_ids"]).last_hidden_state
            else:
                hid = vt.llm(inputs_embeds=x).last_hidden_state
            Q, M = len(opt_pos), max(len(p) for p in opt_pos)
            q_seq = torch.tensor([i for i, spans in enumerate(blocks) for _ in spans], device=dev)
            pos = torch.zeros(Q, M, dtype=torch.long, device=dev)
            valid = torch.zeros(Q, M, dtype=torch.bool, device=dev)
            for i, p in enumerate(opt_pos):
                pos[i, :len(p)] = torch.tensor(p, device=dev)
                valid[i, :len(p)] = True
        h = hid[q_seq[:, None], pos].float()
        is_new = torch.tensor([t == "addressee" for t in tasks], device=dev)[:, None]
        out = torch.where(is_new, self.new_head(h).squeeze(-1), vt.head(h).squeeze(-1))
        return out.masked_fill(~valid, float("-inf"))
